INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63960189', 63960189, 'analyze_legacy', 'Provinsi Sulawesi Selatan', 'provinsi', 'UPT TRANSFUSI DARAH', 'Belanja Suku Cadang-Suku Cadang Alat Kedokteran ( Klem Bengkok )', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 1650000, 'January 2026', 'BLUD', 1, 1, '30 Buah', 'Pengadaan klem bengkok sebagai alat kesehatan penunjang tindakan dan pelayanan medis di UPT/instansi kesehatan. Klem bengkok digunakan untuk menjepit, menahan, atau membantu manipulasi jaringan/alat pada prosedur medis sesuai standar pelayanan. Pekerjaan meliputi penyediaan barang, pengemasan, pengiriman, serta memastikan alat dalam kondisi baik dan layak pakai.', 'Klem bengkok (curved clamp) untuk keperluan medis. Terbuat dari stainless steel berkualitas tinggi, tahan karat dan mudah disterilkan. Desain ujung bengkok untuk memudahkan penggunaan pada area tertentu. Panjang sesuai standar alat medis (mis. ± 14–16 cm atau sesuai kebutuhan). Mekanisme pengunci (ratchet) berfungsi baik dan presisi. Permukaan halus, tidak tajam, dan aman digunakan. Dapat disterilkan dengan metode standar (autoklaf).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1263682);
