INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63960982', 63960982, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Jasa Penyebarluasan Publikasi dan Dokumentasi Program MBG pada Media Nasional', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1200000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6, PKT', '1. Jasa Penyebarluasan Publikasi dan Dokumentasi Program MBG pada Media Nasional 6, PKT', '1. Pra-Produksi (Perencanaan) a. Penyusunan rencana strategis pemberitaan yang mencakup isu utama, target audiens, dan media sasaran. b. Penentuan angle berita, narasumber, dan pendekatan komunikasi yang selaras dengan kebijakan publikasi BGN. c. Penyusunan jadwal pelaksanaan kegiatan publikasi dan distribusi berita. 2. Produksi Konten: a. Penulisan dan penyusunan naskah berita, feature, atau artikel khusus mengenai program BGN dan MBG. b. Peliputan langsung kegiatan/program BGN dan MBG di lapangan apabila diperlukan. c. Koordinasi dengan redaksi media untuk memastikan ketepatan isi, waktu, dan penayangan publikasi. 3. Pasca-Produksi dan Pengelolaan: a. Penyampaian bukti tayang/terbit (hardcopy atau softcopy) dari setiap publikasi yang telah dilaksanakan. b. Penyusunan laporan akhir kegiatan yang memuat dokumentasi, daftar media publikasi, jumlah eksposur, dan analisis hasil pemberitaan. c. Finalisasi dan penyerahan seluruh hasil pekerjaan serta arsip publikasi kepada BGN.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1267284);
