INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63962224', 63962224, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Procurement of PET CT', 'Barang', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 219298695000, 'October 2024', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '5 RS 5 Alkes', 'Pengadaan Alat Kesehatan PET-CT : Lot 1: Procurement of PET-CT dan Lot 2: Procurement of PET-CT. (Paket masih dalam proses pengadaan)', 'Sistem pemindaian yang dirancang untuk mengombinasikan kemampuan tomografi terkomputasi (CT) dan tomografi emisi positron (PET). Sistem ini dapat berupa pemindai CT dan PET yang dipasang pada satu penyangga mekanis yang sama dalam satu gantri, atau pemindai CT dan PET dengan desain terbuka yang memungkinkan penggunaan CT dan PET sebagai sistem pemindaian mandiri. Sistem ini juga dilengkapi dengan meja pemeriksaan, workstation, monitor, serta perangkat lunak yang sesuai untuk menyelaraskan citra CT dan PET. Sistem ini dapat digunakan, bila diperlukan, untuk pemeriksaan CT dan PET secara terpisah tanpa kehilangan kinerja teknis. Sistem ini menyediakan pencitraan fusi (yaitu integrasi) antara citra anatomi yang dihasilkan oleh irisan CT dan citra fungsional (metabolik) dari pemindaian PET yang dilakukan dalam sesi yang sama dengan pasien pada posisi pemeriksaan. Sistem gabungan CT/PET dimaksudkan untuk memfasilitasi evaluasi yang lebih cepat dan lebih akurat, serta umumnya digunakan untuk diagnosis, perencanaan terapi, dan evaluasi respons pengobatan pada pasien kanker, dengan mengarakterisasi penyakit berdasarkan fitur anatomi dan biologisnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1268795);
